} else if (msg.voice) {
  // Las notas de voz de Telegram son OGG/Opus. Va como '.ogg' y NO '.oga': la Media Library
  // de GHL valida por EXTENSIÓN, no por contenido, y rechaza .oga con
  // 400 INVALID_FILE_TYPE. Medido el 2026-08-20 subiendo el MISMO archivo dos veces,
  // byte por byte idéntico, cambiando sólo el nombre: .oga → 400, .ogg → 201.
  // (También aceptan .mp3 y .wav; .m4a también da 400.)
  // Con .oga el audio moría en el upload y NUNCA llegaba a Whisper.
  // El regex de audio de `Normalizar entrada` matchea .ogg igual, así que no cambia nada aguas abajo.
  media = { file_id: msg.voice.file_id, ext: 'ogg', clase: 'nota de voz',
            bytes: Number(msg.voice.file_size || 0) };
